/*
 * @brief Performs direct API invalid param tests for imb_ml_dsa_keypair()
 *        (covering fresh-random and seeded paths via IMB_ML_DSA_KEYGEN_PARAMS) */
static int
test_imb_ml_dsa_keypair(struct IMB_MGR *mgr)
{
        IMB_ML_DSA *self = NULL;
        uint8_t pk[BUFF_SIZE], sk[BUFF_SIZE], seed[BUFF_SIZE];
        int seg_err; /* segfault flag */
        unsigned i;
        volatile int ret = 0;

        seg_err = setjmp(dir_api_param_env);
        if (seg_err) {
                printf("%s: segfault occurred!", __func__);
                return 1;
        }

        if (imb_ml_dsa_new(mgr, IMB_ML_DSA_44, &self) != 0) {
                printf("%s: imb_ml_dsa_new failed\n", __func__);
                return 1;
        }

        struct fn_args {
                IMB_ML_DSA *self;
                uint8_t *pk;
                uint8_t *sk;
                const IMB_ERR exp_err;
        } fn_args[] = { { NULL, pk, sk, IMB_ERR_NULL_CTX },
                        { self, NULL, sk, IMB_ERR_NULL_KEY },
                        { self, pk, NULL, IMB_ERR_NULL_KEY } };

        for (i = 0; i < DIM(fn_args); i++) {
                const struct fn_args *ap = &fn_args[i];
                IMB_ML_DSA_KEYGEN_PARAMS params;
                int r;

                IMB_ML_DSA_KEYGEN_PARAMS_INIT(&params);

                /* fresh-random path: xi_32 == NULL */
                params.xi_32 = NULL;
                params.xi_len = 0;
                r = imb_ml_dsa_keypair(ap->self, ap->pk, sizeof(pk), ap->sk, sizeof(sk), &params);
                if (ml_dsa_param_err(r, ap->exp_err, "imb_ml_dsa_keypair (random)")) {
                        ret = 1;
                        break;
                }

                /* seeded (deterministic) path: xi_32 != NULL */
                params.xi_32 = seed;
                params.xi_len = IMB_ML_DSA_KEYGEN_SEED_BYTES;
                r = imb_ml_dsa_keypair(ap->self, ap->pk, sizeof(pk), ap->sk, sizeof(sk), &params);
                if (ml_dsa_param_err(r, ap->exp_err, "imb_ml_dsa_keypair (xi_32)")) {
                        ret = 1;
                        break;
                }
        }

        /* struct-size mismatch: only meaningful for a valid self/pk/sk combo */
        IMB_ML_DSA_KEYGEN_PARAMS size_params;
        const size_t dsa_bad_size[] = { sizeof(size_params) - 1, sizeof(size_params) + 1, 0 };

        for (i = 0; i < DIM(dsa_bad_size); i++) {
                IMB_ML_DSA_KEYGEN_PARAMS_INIT(&size_params);
                size_params.size = dsa_bad_size[i];
                if (ml_dsa_param_err(
                            imb_ml_dsa_keypair(self, pk, sizeof(pk), sk, sizeof(sk), &size_params),
                            IMB_ERR_PQC_PARAMS, "imb_ml_dsa_keypair (params size)")) {
                        ret = 1;
                        break;
                }
        }
        imb_ml_dsa_free(self);
        return ret;
}

/*
 * @brief Performs direct API invalid param tests for imb_ml_dsa_sign()
 *        (covering ctx and rnd_32 combinations via IMB_ML_DSA_SIGN_PARAMS) */
static int
test_imb_ml_dsa_sign(struct IMB_MGR *mgr)
{
        IMB_ML_DSA *self = NULL, *self_no_key = NULL;
        uint8_t sig[BUFF_SIZE], msg[BUFF_SIZE], ctx[BUFF_SIZE], pk[IMB_ML_DSA_44_PUBKEY_BYTES],
                sk[IMB_ML_DSA_44_PRIVKEY_BYTES], rnd[IMB_ML_DSA_SIGN_RND_BYTES];
        size_t sig_len = 0;
        int seg_err; /* segfault flag */
        unsigned i;
        volatile int ret = 0;

        seg_err = setjmp(dir_api_param_env);
        if (seg_err) {
                printf("%s: segfault occurred!", __func__);
                return 1;
        }

        if (imb_ml_dsa_new(mgr, IMB_ML_DSA_44, &self) != 0 ||
            imb_ml_dsa_new(mgr, IMB_ML_DSA_44, &self_no_key) != 0) {
                printf("%s: imb_ml_dsa_new failed\n", __func__);
                goto exit;
        }
        /* A key must be bound before sign() can be exercised for the other
         * invalid-param cases; self_no_key intentionally has none bound, to
         * exercise the IMB_ERR_PQC_NO_KEY path. */
        if (imb_ml_dsa_keypair(self, pk, sizeof(pk), sk, sizeof(sk), NULL) != 0) {
                printf("%s: imb_ml_dsa_keypair failed\n", __func__);
                ret = 1;
                goto exit;
        }

        struct fn_args {
                IMB_ML_DSA *self;
                uint8_t *sig;
                size_t *sig_len;
                const uint8_t *msg;
                size_t msg_len;
                const uint8_t *ctx;
                size_t ctx_len;
                const IMB_ERR exp_err;
        } fn_args[] = {
                { NULL, sig, &sig_len, msg, BUFF_SIZE, ctx, BUFF_SIZE, IMB_ERR_NULL_CTX },
                { self, NULL, &sig_len, msg, BUFF_SIZE, ctx, BUFF_SIZE, IMB_ERR_NULL_DST },
                { self, sig, NULL, msg, BUFF_SIZE, ctx, BUFF_SIZE, IMB_ERR_NULL_DST },
                { self_no_key, sig, &sig_len, msg, BUFF_SIZE, ctx, BUFF_SIZE, IMB_ERR_PQC_NO_KEY },
                { self, sig, &sig_len, NULL, BUFF_SIZE, ctx, BUFF_SIZE, IMB_ERR_NULL_SRC },
                { self, sig, &sig_len, msg, BUFF_SIZE, NULL, BUFF_SIZE, IMB_ERR_NULL_SRC }
        };

        for (i = 0; i < DIM(fn_args); i++) {
                const struct fn_args *ap = &fn_args[i];
                IMB_ML_DSA_SIGN_PARAMS params;
                int r;

                IMB_ML_DSA_SIGN_PARAMS_INIT(&params);
                params.ctx = ap->ctx;
                params.ctx_len = ap->ctx_len;

                /* hedged (auto-random) path: rnd_32 == NULL */
                params.rnd_32 = NULL;
                params.rnd_len = 0;
                r = imb_ml_dsa_sign(ap->self, ap->sig, ap->sig_len, ap->msg, ap->msg_len, &params);
                if (ml_dsa_param_err(r, ap->exp_err, "imb_ml_dsa_sign (hedged)")) {
                        ret = 1;
                        break;
                }

                /* caller-supplied randomness path: rnd_32 != NULL */
                params.rnd_32 = rnd;
                params.rnd_len = sizeof(rnd);
                r = imb_ml_dsa_sign(ap->self, ap->sig, ap->sig_len, ap->msg, ap->msg_len, &params);
                if (ml_dsa_param_err(r, ap->exp_err, "imb_ml_dsa_sign (rnd_32)")) {
                        ret = 1;
                        break;
                }
        }

        /* struct-size mismatch: only meaningful for a valid, fully-formed call */
        if (ret == 0) {
                IMB_ML_DSA_SIGN_PARAMS params;
                const size_t bad_size[] = { sizeof(params) - 1, sizeof(params) + 1, 0 };

                for (i = 0; i < DIM(bad_size); i++) {
                        IMB_ML_DSA_SIGN_PARAMS_INIT(&params);
                        params.size = bad_size[i];
                        sig_len = sizeof(sig);
                        if (ml_dsa_param_err(
                                    imb_ml_dsa_sign(self, sig, &sig_len, msg, BUFF_SIZE, &params),
                                    IMB_ERR_PQC_PARAMS, "imb_ml_dsa_sign (params size)")) {
                                ret = 1;
                                break;
                        }
                }
        }

        /* context string longer than the FIPS 204 maximum (rejected before
         * params->ctx is dereferenced) */
        if (ret == 0) {
                IMB_ML_DSA_SIGN_PARAMS params;

                IMB_ML_DSA_SIGN_PARAMS_INIT(&params);
                params.ctx = ctx;
                params.ctx_len = IMB_ML_DSA_MAX_CTX_BYTES + 1;
                sig_len = sizeof(sig);
                if (ml_dsa_param_err(imb_ml_dsa_sign(self, sig, &sig_len, msg, BUFF_SIZE, &params),
                                     IMB_ERR_PQC_CTX_LEN, "imb_ml_dsa_sign (ctx len)"))
                        ret = 1;
        }

        /* msg_is_mu set but msg_len is not the mu size */
        if (ret == 0) {
                IMB_ML_DSA_SIGN_PARAMS params;

                IMB_ML_DSA_SIGN_PARAMS_INIT(&params);
                params.msg_is_mu = 1;
                sig_len = sizeof(sig);
                if (ml_dsa_param_err(imb_ml_dsa_sign(self, sig, &sig_len, msg, BUFF_SIZE, &params),
                                     IMB_ERR_PQC_MSG_LEN, "imb_ml_dsa_sign (mu msg len)"))
                        ret = 1;
        }

        /* msg_is_mu set together with a context string */
        if (ret == 0) {
                IMB_ML_DSA_SIGN_PARAMS params;

                IMB_ML_DSA_SIGN_PARAMS_INIT(&params);
                params.msg_is_mu = 1;
                params.ctx = ctx;
                params.ctx_len = 1;
                sig_len = sizeof(sig);
                if (ml_dsa_param_err(
                            imb_ml_dsa_sign(self, sig, &sig_len, msg, IMB_ML_DSA_MU_BYTES, &params),
                            IMB_ERR_PQC_PARAMS, "imb_ml_dsa_sign (mu with ctx)"))
                        ret = 1;
        }

        /* a non-zero reserved field requests an unsupported option */
        for (i = 0; ret == 0 && i < sizeof(((IMB_ML_DSA_SIGN_PARAMS *) NULL)->reserved); i++) {
                IMB_ML_DSA_SIGN_PARAMS params;

                IMB_ML_DSA_SIGN_PARAMS_INIT(&params);
                params.reserved[i] = 1;
                sig_len = sizeof(sig);
                if (ml_dsa_param_err(imb_ml_dsa_sign(self, sig, &sig_len, msg, BUFF_SIZE, &params),
                                     IMB_ERR_PQC_PARAMS, "imb_ml_dsa_sign (params reserved)"))
                        ret = 1;
        }
exit:
        imb_ml_dsa_free(self);
        imb_ml_dsa_free(self_no_key);
        return ret;
}

